<?php
$subtotal=0;foreach($products as $p){$price=(float)$p['sale_price']>0?(float)$p['sale_price']:(float)$p['price'];$subtotal+=$price*(int)$_SESSION['cart'][$p['id']];}
$shipping=($customer['shipping_method']??'DOMICILIO')==='RETIRO'?0:25;$total=$subtotal+$shipping;
?>
