   <form method="post" action="/?r=processPayment" id="paymentForm" autocomplete="off" novalidate>
    <input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="card_last4" id="card_last4"><input type="hidden" name="card_brand" id="card_brand">
    <div class="payment-visual"><div class="chip"></div><div class="visual-number" id="visualNumber">•••• •••• •••• ••••</div><div class="visual-bottom"><span id="visualName">NOMBRE DEL TITULAR</span><span id="visualExpiry">MM/AA</span></div></div>
